// Agent patches: a project's delta to the shipped agents, kept in .claude/proteus-agents.json
// (.codex/proteus-agents.json on Codex) as {"<agent>": {tools: {add, remove}, model, effort, append}}.
// apply() writes <harness dir>/agents/<agent>.md (.toml on Codex) from the shipped agent plus its patch,
// marked as generated, so a shipped change still flows through on every --project, --update and
// session-start sync. A marked file whose entry is gone is removed. Generated files are git-excluded
// (machine-local, like the hooks); the patch file is the project's and committed, unless guest mode.
// A bad file (invalid JSON, an unknown agent or key, a wrong type) returns {error} and writes nothing.
// A link the repo commits at .claude, its agents/ or a generated file's path (to ~/.claude, say) is
// never written or removed through: it is listed in refused, and left alone (#22).
// Used by install.js and proteus-autostart.js; no exit codes of its own, and it never throws.
"use strict";
const fs = require("fs");
const path = require("path");
const lib = require(path.join(__dirname, "proteus-lib.js"));

// first text of a generated file's marker line (a YAML comment in the frontmatter, or the TOML's
// first line); "# generated by proteus" is the Codex roles' marker, so the global sync agrees
const MARK = "# generated by proteus from proteus-agents.json";
// frontmatter keys the shipped agents use, plus the prompt; Codex roles carry no model, effort or
// tool list (the ladder picks the model per spawn), so only append applies there
const KEYS = { claude: ["tools", "model", "effort", "append"], codex: ["append"] };
const DIR = (h) => `.${h === "codex" ? "codex" : "claude"}`;
const patchFile = (root, h) => path.join(root, DIR(h), "proteus-agents.json");
const agentsDir = (root, h) => path.join(root, DIR(h), "agents");
const relOf = (root, p) => path.relative(root, p).split(path.sep).join("/");
const norm = (s) => String(s).replace(/^﻿/, "").replace(/\r\n/g, "\n");
const read = (p) => { try { return fs.readFileSync(p, "utf8"); } catch { return null; } };
const isGenerated = (text) => text !== null && norm(text).split("\n", 2).some((l) => l.startsWith(MARK));
const lstat = (p) => { try { return fs.lstatSync(p); } catch { return null; } };
// root (resolved once) joined with segs: each component below root is missing or a real directory,
// never a link (a junction on Windows lstats as one too) or a file
function ownable(root, segs) {
  let d;
  try { d = fs.realpathSync(root); } catch { d = path.resolve(root); }
  for (const s of segs) {
    d = path.join(d, s);
    const st = lstat(d);
    if (!st) return true;
    if (st.isSymbolicLink() || !st.isDirectory()) return false;
  }
  return true;
}

// frontmatter as fields [{key, lines}] (key "" for comments and blank lines) and the body; null without one
function split(text) {
  const m = /^---\n([\s\S]*?)\n---\n?([\s\S]*)$/.exec(norm(text));
  if (!m) return null;
  const fields = [];
  for (const l of m[1].split("\n")) {
    const k = /^([A-Za-z_][\w-]*):/.exec(l);
    if (k) fields.push({ key: k[1], lines: [l] });
    else if (/^\s/.test(l) && fields.length && fields[fields.length - 1].key) fields[fields.length - 1].lines.push(l);
    else fields.push({ key: "", lines: [l] });
  }
  return { fields, body: m[2] };
}
// a tools field as a list: block (- Read) or inline (tools: Read, Grep / [Read, Grep])
function toolList(f) {
  const inline = f.lines[0].replace(/^tools:\s*/, "").replace(/^\[|\]$/g, "").trim();
  const block = f.lines.slice(1).flatMap((l) => { const m = /^\s*-\s*(.+?)\s*$/.exec(l); return m ? [m[1]] : []; });
  return [...(inline ? inline.split(",") : []), ...block].flatMap((t) => { const v = t.trim().replace(/^(["'])(.*)\1$/, "$2"); return v ? [v] : []; });
}
// a plain YAML scalar when safe, else a JSON string (valid YAML double-quoted)
const scalar = (s) => (/^[\w*().@/[\]-][^#]*$/.test(s) && !/: |:$/.test(s) && s.trim() === s ? s : JSON.stringify(s));

// the shipped agent's markdown with the patch applied; throws an Error naming the entry when the
// patch does not fit the shipped text
function patchAgent(text, patch, name) {
  const s = split(text);
  if (!s) throw new Error(`"${name}": the shipped agent has no frontmatter to patch`);
  const fields = s.fields.map((f) => ({ ...f, lines: [...f.lines] }));
  if (patch.tools) {
    const f = fields.find((x) => x.key === "tools");
    if (!f) throw new Error(`"${name}".tools: the shipped agent has no tools list (it gets every tool), so there is nothing to add to or remove from`);
    const remove = patch.tools.remove || [];
    const list = toolList(f).filter((t) => !remove.includes(t));
    for (const t of patch.tools.add || []) if (!list.includes(t)) list.push(t);
    f.lines = ["tools:", ...list.map((t) => `  - ${scalar(t)}`)];
  }
  for (const k of ["model", "effort"]) {
    if (patch[k] === undefined) continue;
    const line = `${k}: ${scalar(patch[k])}`, f = fields.find((x) => x.key === k);
    if (f) f.lines = [line];
    else {
      // beside the shipped model line, or after the name
      const at = fields.findIndex((x) => x.key === "model") + 1 || fields.findIndex((x) => x.key === "name") + 1;
      fields.splice(at, 0, { key: k, lines: [line] });
    }
  }
  let body = s.body;
  if (typeof patch.append === "string" && patch.append.trim()) body = `${body.replace(/\s+$/, "")}\n\n${norm(patch.append).trim()}\n`;
  return `---\n${fields.flatMap((f) => f.lines).join("\n")}\n---\n${body}`;
}

// the marker goes inside the frontmatter of a markdown agent, else first (replacing the TOML's own header)
function mark(text, file, h) {
  const line = `${MARK} and agents/${file}; edit ${DIR(h)}/proteus-agents.json instead`;
  if (text.startsWith("---\n")) return `---\n${line}\n${text.slice(4)}`;
  return `${line}\n${text.replace(/^# generated by proteus[^\n]*\n/, "")}`;
}

// frontmatter keys that differ between two agent texts, plus "prompt" when the bodies differ
function diffFields(shipped, copy) {
  const a = split(shipped), b = split(copy);
  if (!a || !b) return ["frontmatter"];
  const map = (s) => new Map(s.fields.filter((f) => f.key).map((f) => [f.key, f.lines.map((l) => l.trimEnd()).join("\n")]));
  const ma = map(a), mb = map(b);
  const keys = [...new Set([...ma.keys(), ...mb.keys()])].filter((k) => ma.get(k) !== mb.get(k));
  if (a.body.trim() !== b.body.trim()) keys.push("prompt");
  return keys;
}

const STR = (v) => typeof v === "string" && v.trim() !== "" && !/[\r\n]/.test(v);
// the patch file as {patches} or {error}; names: the shipped agents' names (file names without .md)
function load(root, h, names) {
  const file = patchFile(root, h), rel = relOf(root, file);
  const text = read(file);
  if (text === null) return { patches: {}, file: rel, present: false };
  let v;
  try { v = JSON.parse(norm(text).trim() || "{}"); } catch (e) { return { error: `${rel} is not valid JSON (${e.message})`, file: rel }; }
  if (!v || typeof v !== "object" || Array.isArray(v)) return { error: `${rel} must be a JSON object of agent name to patch`, file: rel };
  const keys = KEYS[h] || KEYS.claude;
  const bad = (msg) => ({ error: `${rel}: ${msg}`, file: rel });
  for (const [name, p] of Object.entries(v)) {
    if (!names.includes(name)) return bad(`"${name}" is not a shipped agent (shipped: ${names.join(", ")})`);
    if (!p || typeof p !== "object" || Array.isArray(p)) return bad(`"${name}" must be an object such as {"append": "..."}`);
    for (const [k, x] of Object.entries(p)) {
      if (!keys.includes(k)) {
        return bad(KEYS.claude.includes(k) ? `"${name}".${k}: Codex roles take no ${k} (no model, effort or tool list; the ladder picks the model per spawn); only append applies`
          : `"${name}".${k} is not a patch key (allowed: ${keys.join(", ")})`);
      }
      if ((k === "model" || k === "effort") && !(STR(x) && !/\s/.test(x))) return bad(`"${name}".${k} must be one word, such as ${k === "model" ? '"opus"' : '"high"'}`);
      if (k === "append" && typeof x !== "string") return bad(`"${name}".append must be a string`);
      if (k === "tools") {
        if (!x || typeof x !== "object" || Array.isArray(x)) return bad(`"${name}".tools must be {"add": [...], "remove": [...]}`);
        for (const [tk, list] of Object.entries(x)) {
          if (tk !== "add" && tk !== "remove") return bad(`"${name}".tools.${tk} is not a tools key (allowed: add, remove)`);
          if (!Array.isArray(list) || !list.every(STR)) return bad(`"${name}".tools.${tk} must be a list of tool names`);
        }
      }
    }
  }
  return { patches: v, file: rel, present: true };
}

// what apply() would do: {error} or {write: [{path, text}], remove: [path], kept: [{path, name}], refused: [path], file}
// home: the Proteus checkout (shipped agents in home/agents); ad: the harness adapter (name, agentFile)
function plan(root, home, ad) {
  const h = ad && ad.name === "codex" ? "codex" : "claude";
  let shipped = [];
  try { shipped = fs.readdirSync(path.join(home, "agents")).filter((f) => f.endsWith(".md")).sort(); } catch {}
  const names = shipped.map((f) => f.slice(0, -3));
  const l = load(root, h, names);
  if (l.error) return { error: l.error, file: l.file };
  const dir = agentsDir(root, h), out = { write: [], remove: [], kept: [], refused: [], file: l.file, present: l.present, harness: h };
  if (!ownable(root, [DIR(h), "agents"])) { out.refused.push(dir); return out; }
  const want = new Set();
  for (const [name, p] of Object.entries(l.patches)) {
    const f = `${name}.md`;
    let text;
    try { text = patchAgent(read(path.join(home, "agents", f)) || "", p, name); } catch (e) { return { error: `${l.file}: ${e.message}`, file: l.file }; }
    const a = ad.agentFile(f, text);
    if (!a) return { error: `${l.file}: "${name}": the shipped agent has no frontmatter to patch`, file: l.file };
    const dest = path.join(dir, a.name);
    want.add(a.name);
    if (lstat(dest) && lstat(dest).isSymbolicLink()) { out.refused.push(dest); continue; }
    const cur = read(dest);
    // an unmarked file there is the project's own copy: never overwritten
    if (cur !== null && !isGenerated(cur)) { out.kept.push({ path: dest, name }); continue; }
    const next = mark(norm(a.text), f, h);
    if (cur === null || norm(cur) !== next) out.write.push({ path: dest, text: next });
  }
  let have = [];
  try { have = fs.readdirSync(dir); } catch {}
  for (const f of have) {
    if (want.has(f)) continue;
    const p = path.join(dir, f);
    try { if (!fs.lstatSync(p).isFile()) continue; } catch { continue; }
    if (isGenerated(read(p))) out.remove.push(p);
  }
  return out;
}

// info/exclude gets each generated file (and in guest mode the patch file); a line already there stays
function exclude(root, rels) {
  const common = lib.gitCommonDir(root);
  if (!common || !rels.length) return;
  const file = path.join(common, "info", "exclude");
  const cur = read(file) || "";
  const have = cur.split(/\r?\n/), add = [...new Set(rels)].filter((l) => !have.includes(l));
  if (!add.length) return;
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.appendFileSync(file, (cur && !cur.endsWith("\n") ? "\n" : "") + add.join("\n") + "\n");
}

// carries the plan out: {error} or {written, removed, kept: [{path, name}], refused, file} with paths relative
// to root, "/"-separated. remove: removes a file and returns true (install.js passes its guarded remover).
function apply(root, home, ad, remove) {
  try {
    const p = plan(root, home, ad);
    if (p.error) return p;
    const r = { written: [], removed: [], kept: p.kept.map((k) => ({ ...k, path: relOf(root, k.path) })), refused: p.refused.map((x) => relOf(root, x)), file: p.file, present: p.present };
    for (const w of p.write) {
      fs.mkdirSync(path.dirname(w.path), { recursive: true });
      fs.writeFileSync(w.path, w.text);
      r.written.push(relOf(root, w.path));
    }
    for (const x of p.remove) {
      const gone = remove ? remove(x) : (fs.unlinkSync(x), true);
      if (gone) r.removed.push(relOf(root, x));
    }
    const ex = p.write.map((w) => relOf(root, w.path));
    if (lib.guestDir(root) && p.present) ex.push(p.file);
    exclude(root, ex);
    return r;
  } catch (e) {
    return { error: `agent patches not applied: ${e.message}` };
  }
}

module.exports = { MARK, KEYS, patchFile, isGenerated, patchAgent, diffFields, load, plan, apply };
